<script>
  import "$lib/styles/tennis.css";
  import ServeComparison from '$lib/components/tennis/ServeComparison.svelte';
  import { onMount, onDestroy } from 'svelte';
  import { page } from '$app/stores';
  import { goto } from '$app/navigation';
  import { userId } from '$lib/stores/auth.js';
  import { authenticatedFetch } from '$lib/services/authenticated-fetch.js';
  import { SURFACES, CIRCUITS, calendarDays } from '$lib/tennis/domain.js';
  import { ArrowUpRight, Search, RefreshCw, CircleDot, ShieldCheck, Info, Clock3, ChevronRight, Activity } from 'lucide-svelte';
  let mounted=false,demo=false,timezone='America/Guayaquil',dayIndex=0,gender='all',surface='all',circuit='all',search='';
  let calendar=null,detail=null,selected='',loading=false,detailLoading=false,failure='',detailFailure='',tab='overview',saved='';
  let listController,detailController,signature='',listGeneration=0,detailGeneration=0;
  onMount(()=>{mounted=true;});
  onDestroy(()=>{listController?.abort();detailController?.abort();});
  $: demo=$page.url.searchParams.get('demo')==='1';
  $: if(mounted && signature!==`${demo}:${$userId}:${timezone}:${dayIndex}`){signature=`${demo}:${$userId}:${timezone}:${dayIndex}`;loadCalendar();}
  $: players=Object.fromEntries((calendar?.players||[]).map(p=>[p.id,p]));
  $: detailPlayers=Object.fromEntries((detail?.players||[]).map(p=>[p.id,p]));
  $: matches=(calendar?.matches||[]).filter(m=>(gender==='all'||players[m.a]?.gender===gender)&&(surface==='all'||m.surface===surface)&&(circuit==='all'||m.circuit===circuit)&&`${players[m.a]?.name} ${players[m.b]?.name} ${m.tournament}`.toLowerCase().includes(search.toLowerCase()));
  $: if(calendar && !loading && !matches.some(m=>m.id===selected)){selected=matches[0]?.id||'';detail=null;if(selected)loadDetail(selected);else{detailController?.abort();detailGeneration++;detailLoading=false;detailFailure='';}}
  $: analysis=detail?.analysis;
  $: matchup=detail?.match;
  $: pair=matchup?[detailPlayers[matchup.a],detailPlayers[matchup.b]]:[];
  const statuses={scheduled:'Programado',live:'En juego',finished:'Finalizado',postponed:'Aplazado',cancelled:'Cancelado'};
  const percent=(won,played)=>played?`${Math.round(won/played*100)}%`:'—';
  const initials=name=>(name||'').split(' ').map(s=>s[0]).slice(0,2).join('');
  const clock=value=>new Intl.DateTimeFormat('es',{timeZone:timezone,hour:'2-digit',minute:'2-digit'}).format(new Date(value));
  const date=value=>new Intl.DateTimeFormat('es',{timeZone:timezone,day:'numeric',month:'short'}).format(new Date(value));
  function endpoint(extra={}){const query=new URLSearchParams({tz:timezone,date:calendarDays(Date.now(),timezone)[dayIndex],...(demo?{demo:'1'}:{}),...(demo&&extra.match&&calendar?{demoAt:calendar.fetchedAt}:{}),...extra});return `/api/tennis?${query}`;}
  async function read(url,signal){const response=await (demo?fetch(url,{signal}):authenticatedFetch(url,{signal}));const body=await response.json();if(!response.ok)throw new Error(body.error||body.message||'No se pudo consultar el tenis.');return body;}
  async function loadCalendar(){
    const generation=++listGeneration;listController?.abort();detailController?.abort();detailGeneration++;listController=new AbortController();loading=true;failure='';calendar=null;detail=null;selected='';saved='';
    try{const body=await read(endpoint(),listController.signal);if(generation===listGeneration)calendar=body;}
    catch(e){if(e.name!=='AbortError'&&generation===listGeneration)failure=e.message;}
    finally{if(generation===listGeneration)loading=false;}
  }
  async function loadDetail(id){
    selected=id;detail=null;saved='';detailFailure='';tab='overview';const generation=++detailGeneration;detailController?.abort();detailController=new AbortController();detailLoading=true;
    try{const body=await read(endpoint({match:id}),detailController.signal);if(generation===detailGeneration)detail=body;}
    catch(e){if(e.name!=='AbortError'&&generation===detailGeneration)detailFailure=e.message;}
    finally{if(generation===detailGeneration)detailLoading=false;}
  }
  async function saveAnalysis(){
    if(demo||!matchup||saved==='Guardando…')return;const id=matchup.id;saved='Guardando…';
    try{const res=await authenticatedFetch('/api/tennis',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({matchId:id})});const body=await res.json();if(!res.ok)throw new Error(body.error);if(selected===id)saved='Análisis archivado con su fuente y versión.';}
    catch(e){if(selected===id)saved=e.message;}
  }
  function resetFilters(){gender='all';surface='all';circuit='all';search='';}
  async function setDemo(value){await goto(value?'/tennis?demo=1':'/tennis',{replaceState:true,keepFocus:true,noScroll:true});}
</script>

<div class="tennis tennis-theme">
  <header class="hero"><div><p class="eyebrow"><span class="live-dot"></span> NIOSPORTS / TENNIS LAB</p><h1>Lee el partido.<br/><em>Entiende la ventaja.</em></h1><p class="subtitle">Dos jugadores. Una superficie. Todo el contexto que necesitas poner en perspectiva.</p></div><div class="court" aria-hidden="true"><div class="court-lines"><i></i><b></b><span></span></div><span class="ball"></span><small>HARD / CLAY / GRASS</small></div></header>

  <div class="mode-banner" class:demo><span><strong>{demo?'DEMO INTERACTIVA':'DATOS DEL PROVEEDOR'}</strong> {demo?'Jugadores, partidos y cifras ficticios. No son pronósticos reales.':'La cobertura y actualidad dependen de la información recibida.'}</span><button on:click={()=>setDemo(!demo)}>{demo?'Ver estado real':'Explorar demostración'} <ArrowUpRight size={14}/></button></div>

  <div class="toolbar"><div class="day-picker" role="group" aria-label="Día del calendario"><button class:active={dayIndex===0} aria-pressed={dayIndex===0} on:click={()=>dayIndex=0}>Hoy</button><button class:active={dayIndex===1} aria-pressed={dayIndex===1} on:click={()=>dayIndex=1}>Mañana</button></div><div class="gender-picker" role="group" aria-label="Categoría"><button class:active={gender==='all'} aria-pressed={gender==='all'} on:click={()=>gender='all'}>Todos</button><button class:active={gender==='men'} aria-pressed={gender==='men'} on:click={()=>gender='men'}>Masculino</button><button class:active={gender==='women'} aria-pressed={gender==='women'} on:click={()=>gender='women'}>Femenino</button></div><label class="zone">Zona horaria<select aria-label="Zona horaria" bind:value={timezone}><option>America/Guayaquil</option><option>Europe/Madrid</option><option>America/New_York</option><option>UTC</option></select></label><button class="refresh" on:click={loadCalendar} disabled={loading} aria-label="Actualizar calendario"><RefreshCw size={16}/></button></div>
  <div class="filter-row"><label class="search"><Search size={16}/><input aria-label="Buscar jugador o torneo" bind:value={search} placeholder="Buscar jugador o torneo…"/></label><select aria-label="Superficie" bind:value={surface}><option value="all">Todas las superficies</option>{#each Object.entries(SURFACES) as [value,label]}<option {value}>{label}</option>{/each}</select><select aria-label="Circuito" bind:value={circuit}><option value="all">Todos los circuitos</option>{#each CIRCUITS as name}<option value={name}>{name}</option>{/each}</select><span class="count">{matches.length} partidos · Individuales</span></div>

  {#if failure}<div class="empty main-error" role="alert"><Activity size={30}/><h2>{!demo&&!$userId?'Tu acceso al tenis empieza aquí':'El calendario no está disponible'}</h2><p>{failure}</p><div>{#if !demo&&!$userId}<a class="primary" href="/login">Iniciar sesión</a>{/if}<button on:click={()=>setDemo(true)}>Explorar ejemplo visual <ArrowUpRight size={15}/></button><button on:click={loadCalendar}>Reintentar</button></div></div>
  {:else if loading}<div class="loading" role="status"><span class="loading-dot"></span> Consultando calendario y cobertura…</div>
  {:else if calendar}
    <div class="source-line"><span><ShieldCheck size={13}/> {calendar.provider}</span><span>Actualizado {date(calendar.fetchedAt)} · {clock(calendar.fetchedAt)} {calendar.stale?'· DATOS ANTIGUOS':''}</span></div>
    <div class="workspace">
      <aside class="schedule" aria-label="Partidos del día"><div class="schedule-title"><h2>Orden de juego</h2><span>{calendar.days[dayIndex]}</span></div>
        {#each matches as match(match.id)}<button class="match" class:selected={selected===match.id} aria-pressed={selected===match.id} on:click={()=>loadDetail(match.id)}><div class="match-meta"><span class="surface-dot" class:clay={match.surface==='clay'} class:grass={match.surface==='grass'}></span><span>{match.circuit} · {SURFACES[match.surface]}</span><time>{clock(match.startAt)}</time></div><p class="tournament">{match.tournament}</p><div class="player-line"><span>{players[match.a]?.name||'Jugador por confirmar'}</span><small>{players[match.a]?.rank?`#${players[match.a].rank}`:'—'}</small></div><div class="player-line"><span>{players[match.b]?.name||'Jugador por confirmar'}</span><small>{players[match.b]?.rank?`#${players[match.b].rank}`:'—'}</small></div><div class="match-bottom"><span>{match.round||'Ronda por confirmar'} · {statuses[match.status]}</span><ChevronRight size={13}/></div></button>{:else}<div class="empty"><h3>Sin partidos en esta vista</h3><p>Puede no haber encuentros en la cobertura recibida o coincidentes con tus filtros.</p><button on:click={resetFilters}>Limpiar filtros</button></div>{/each}
      </aside>

      <section class="report" aria-label="Informe del partido">
        {#if detailLoading}<div class="loading" role="status">Preparando comparación…</div>
        {:else if detailFailure}<div class="empty" role="alert"><h2>No se pudo cargar el informe</h2><p>{detailFailure}</p><button on:click={()=>loadDetail(selected)}>Reintentar</button></div>
        {:else if detail&&analysis&&matchup}
          <div class="report-head"><span class="eyebrow">MATCH INTELLIGENCE</span><span>{matchup.circuit} · {matchup.bestOf} sets máx.</span></div>
          <div class="versus">{#each pair as player,i}<div class="athlete"><span class="avatar" class:second={i===1}>{initials(player?.name)}</span><span class="athlete-country">{player?.country||'País no disponible'} · {player?.rank?`Ranking #${player.rank}`:'Sin ranking'}</span><h2><a href={`/tennis/player/${encodeURIComponent(player.id)}?${new URLSearchParams({tz:timezone,...(demo?{demo:"1",demoAt:calendar.fetchedAt}:{})})}`}>{player?.name} ↗</a></h2><span class="form" aria-label={`Últimos resultados de ${player?.name}`}>{#each analysis.summaries[i].recent.slice(0,5) as result}<span class:loss={!result.won} title={`${result.won?'Victoria':'Derrota'} · ${date(result.endedAt)}`}>{result.won?'V':'D'}</span>{/each}</span></div>{#if i===0}<div class="vs"><span>VS</span><small>{clock(matchup.startAt)}</small></div>{/if}{/each}</div>
          <div class="match-context"><span><CircleDot size={14}/> {SURFACES[matchup.surface]} · {matchup.indoor===true?'Indoor':matchup.indoor===false?'Outdoor':'Recinto sin confirmar'}</span><span>{matchup.tournament} · {date(matchup.startAt)}</span></div>
          <div class="report-tabs" role="group" aria-label="Sección del informe">{#each [['overview','Panorama'],['surface','Superficies'],['service','Saque y resto'],['h2h','Cara a cara'],['health','Estado físico']] as [value,label]}<button class:active={tab===value} aria-pressed={tab===value} on:click={()=>tab=value}>{label}</button>{/each}</div>

          {#if tab==='overview'}
            <div class="forecast" class:abstained={analysis.status==='abstained'}><div class="forecast-label"><span class="eyebrow">{analysis.status==='abstained'?'ABSTENCIÓN DEL MOTOR':'LECTURA DEL MODELO'}</span><span class="experimental">{demo?'SIMULACIÓN':'EXPERIMENTAL'}</span></div>
              {#if analysis.probabilityA!==null}<div class="probabilities"><strong>{Math.round(analysis.probabilityA*100)}<small>%</small></strong><span>Probabilidad estimada<br/>de ganar el partido</span><strong>{Math.round((1-analysis.probabilityA)*100)}<small>%</small></strong></div><div class="prob-bar"><span style={`width:${analysis.probabilityA*100}%`}></span></div><p>Combina la valoración general y la valoración en {SURFACES[matchup.surface].toLowerCase()}. Es un modelo inicial, sin calibración demostrada.</p>
              {:else}<h3>Este partido necesita más información.</h3>{#each analysis.reasons as reason}<p class="reason"><Info size={14}/>{reason}</p>{/each}{/if}
            </div>
            <div class="section-heading"><h3>La comparación, en datos</h3><span>Historial disponible · temporada {new Date(matchup.startAt).getUTCFullYear()}</span></div>
            <div class="compare"><div class="compare-row"><b>{analysis.summaries[0].season.won} / {analysis.summaries[0].season.played}</b><span>Victorias / partidos</span><b>{analysis.summaries[1].season.won} / {analysis.summaries[1].season.played}</b></div><div class="compare-row"><b>{percent(analysis.summaries[0].season.won,analysis.summaries[0].season.played)}</b><span>Porcentaje de victorias</span><b>{percent(analysis.summaries[1].season.won,analysis.summaries[1].season.played)}</b></div><div class="compare-row"><b>{analysis.ratings[0].surface}</b><span>Elo en esta superficie</span><b>{analysis.ratings[1].surface}</b></div><div class="compare-row"><b>{analysis.ratings[0].surfaceMatches}</b><span>Muestra en esta superficie</span><b>{analysis.ratings[1].surfaceMatches}</b></div><div class="compare-row"><b>—</b><span>Cuotas del mercado · no conectadas</span><b>—</b></div></div>
            <div class="explain"><h3>Cómo leer este informe</h3><p>Las valoraciones cambian con los rivales y resultados previos. Los datos posteriores al partido y los abandonos no entran en el cálculo inicial. El historial recibido puede no representar toda la carrera.</p><details><summary>Ver metodología y límites</summary><p>Base Elo 1500; actualización K=24; mezcla 50% general y 50% superficie. Mínimos: 20 partidos y 8 en superficie por jugador. Sin datos nuevos en seis horas o con incidencia física reportada, el motor se abstiene.</p>{#each analysis.warnings as warning}<p>{warning}</p>{/each}<p>Versión {analysis.modelVersion} · Corte: {date(analysis.asOf)} {clock(analysis.asOf)}</p></details></div>
          {:else if tab==='surface'}
            <div class="section-heading"><h3>Una superficie cambia el contexto.</h3><span>Temporada · partidos completos registrados</span></div>
            <div class="surface-grid">{#each analysis.summaries as summary,i}<article><h3>{pair[i]?.name}</h3>{#each summary.surfaces as row}<div class="surface-stat"><div><span>{SURFACES[row.surface]}</span><strong>{percent(row.won,row.played)}</strong></div><div class="stat-track"><i style={`width:${row.played?row.won/row.played*100:0}%`}></i></div><small>{row.won} victorias / {row.played} partidos</small></div>{/each}<p class="best">Mayor tasa observada: <strong>{summary.bestSurface?SURFACES[summary.bestSurface]:'Muestra insuficiente'}</strong></p><small>Mínimo 5 partidos por superficie. No implica una ventaja futura.</small></article>{/each}</div>
          {:else if tab==='service'}
            <ServeComparison stats={analysis.serviceStats} names={pair.map(p=>p.name)}/>
          {:else if tab==='h2h'}
            <div class="h2h-score"><strong>{analysis.h2h.aWins}</strong><div><span class="eyebrow">ENFRENTAMIENTOS DIRECTOS</span><p>{analysis.h2h.aWins+analysis.h2h.bWins} partidos completos registrados</p></div><strong>{analysis.h2h.bWins}</strong></div>
            {#each analysis.h2h.matches as match}<div class="history-row"><span>{date(match.endedAt)} · {SURFACES[match.surface]}</span><strong>{detailPlayers[match.winner]?.name||'Ganador'} <small>ganó</small></strong></div>{:else}<div class="empty"><h3>Sin enfrentamientos en el historial recibido</h3><p>No equivale a confirmar que nunca se hayan enfrentado.</p></div>{/each}<p class="context-note">El H2H es contexto, no una probabilidad. No se usa como un ajuste adicional del motor.</p>
          {:else}
            <div class="section-heading"><h3>Información física, con fuente.</h3><span>Sin informes no significa sin lesiones</span></div>
            {#each analysis.injuryReports as report,i}<article class="health-card"><div><Activity size={18}/><h3>{pair[i]?.name}</h3></div>{#if report}<strong>{report.status==='reported'?'Incidencia reportada':'Actualización de recuperación'}</strong><p>{report.title}</p><a href={report.sourceUrl} target="_blank" rel="noopener noreferrer">Consultar fuente <ArrowUpRight size={14}/></a><small>Publicado {date(report.publishedAt)} · {clock(report.publishedAt)}</small>{:else}<strong>Estado no confirmado</strong><p>No tenemos un informe documentado disponible. No se asume que el jugador esté sano ni lesionado.</p>{/if}</article>{/each}
          {/if}
          <div class="report-footer"><span><Clock3 size={12}/> Fuente: {detail.provider}</span>{#if !demo}<button on:click={saveAnalysis} disabled={saved==='Guardando…'}>Archivar análisis</button>{/if}</div>{#if saved}<p class="save-status" role="status">{saved}</p>{/if}
        {:else}<div class="empty"><CircleDot size={32}/><h2>Elige un partido para explorar.</h2><p>La comparación aparecerá aquí, con sus fuentes y límites.</p></div>{/if}
      </section>
    </div>
    <details class="coverage"><summary>Cobertura y disponibilidad de datos</summary><p>Circuitos declarados por la fuente: {calendar.coverage.join(' · ')||'Ninguno'}. Solo individuales. La ausencia de un partido no demuestra que no exista: depende de la cobertura contratada y la última actualización.</p><p>Lesiones: solo informes documentados. Saque y resto: se muestran si el proveedor entrega conteos verificables. Cuotas: no conectadas. Ninguna ausencia se sustituye por ceros.</p></details>
  {/if}
</div>

<style>
  .schedule{scrollbar-width:thin;scrollbar-color:#526846 var(--tennis-surface)}
  .tennis{max-width:1460px;margin:auto;padding:36px 32px 100px;color:var(--tennis-text);font-family:var(--font-sans)}.hero{display:flex;justify-content:space-between;align-items:center;gap:25px;margin-bottom:30px}.eyebrow{font-size:12px;letter-spacing:2px;color:var(--muted);display:flex;align-items:center;gap:8px}.live-dot{width:6px;height:6px;background:var(--lime);border-radius:50%}h1{font-size:clamp(32px,4vw,52px);font-weight:500;line-height:1.1;letter-spacing:-2px;margin:18px 0}em{font-style:normal;color:var(--lime)}.subtitle{font-size:12px;color:var(--muted);max-width:440px;line-height:1.8}.court{width:210px;height:135px;background:#243e31;border:1px solid #456251;border-radius:9px;position:relative;transform:rotate(-7deg);flex-shrink:0;margin-right:15px}.court-lines{position:absolute;inset:15px 20px;border:1px solid #bedac770}.court-lines:before,.court-lines:after{content:'';position:absolute;top:14%;bottom:14%;width:28%;border:1px solid #bedac760}.court-lines:before{left:22%}.court-lines:after{right:22%}.court-lines i{height:1px;position:absolute;background:#bedac770;left:0;right:0;top:14%}.court-lines b{height:1px;position:absolute;background:#bedac770;left:0;right:0;bottom:14%}.court-lines span{position:absolute;left:50%;top:-10px;bottom:-10px;border-left:2px dotted #eaf7e9a0}.ball{position:absolute;width:22px;height:22px;border-radius:50%;background:#d5ef8b;bottom:25px;left:50px;box-shadow:5px 7px 7px #0006}.court small{position:absolute;bottom:-22px;right:0;font-size:12px;letter-spacing:2px;color:var(--muted)}button,select,input{font:inherit}button{cursor:pointer;color:inherit;border:1px solid var(--tennis-border);border-radius:6px;background:var(--tennis-raised);padding:10px 13px;font-size:12px;display:inline-flex;gap:8px;align-items:center;justify-content:center}button:hover{border-color:#d5ef8b70}button:disabled{opacity:.5;cursor:wait}button.active{color:var(--tennis-surface);background:var(--lime);border-color:var(--lime)}button:focus-visible,a:focus-